import { useEffect, useMemo, useState, type FormEvent } from 'react'
import { MapContainer, TileLayer, CircleMarker, Popup, useMap } from 'react-leaflet'
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { Activity, AlertTriangle, ArrowDownRight, ArrowRight, ArrowUpRight, Bell, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, ClipboardList, Clock3, Database, Gauge, Layers3, MapPin, Menu, RefreshCw, Search, Settings2, ShieldAlert, SlidersHorizontal, Sparkles, TrafficCone, X } from 'lucide-react'
import 'leaflet/dist/leaflet.css'
import './App.css'
import './ModelLab.css'
import './RandomForest.css'

const API = import.meta.env.VITE_API_BASE_URL?.replace(/\/$/, '')
type Page = 'Overview' | 'Live Map' | 'Priority Queue' | 'Incidents' | 'Complaints' | 'Forecasts' | 'Model Lab' | 'Alerts' | 'Settings' | 'Location Detail'
type Row = Record<string, any>
const navigation: { name: Page; icon: typeof Activity; group: string }[] = [
  { name: 'Overview', icon: Gauge, group: 'WORKSPACE' }, { name: 'Live Map', icon: MapPin, group: 'WORKSPACE' },
  { name: 'Priority Queue', icon: ClipboardList, group: 'WORKSPACE' }, { name: 'Incidents', icon: TrafficCone, group: 'MONITOR' },
  { name: 'Complaints', icon: Activity, group: 'MONITOR' }, { name: 'Model Lab', icon: Sparkles, group: 'ANALYTICS' },
  { name: 'Forecasts', icon: Activity, group: 'ANALYTICS' }, { name: 'Alerts', icon: Bell, group: 'ANALYTICS' }, { name: 'Settings', icon: Settings2, group: 'SYSTEM' },
]
const fmt = (value: number | null | undefined, digits = 0) => value == null || !Number.isFinite(Number(value)) ? '—' : Number(value).toLocaleString(undefined, { maximumFractionDigits: digits })
const shortDate = (value: string) => value ? new Date(value).toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) : ''
const roadColor = (score: number) => score >= 75 ? '#ba5142' : score >= 55 ? '#c38d3d' : '#287a70'

async function api<T>(path: string, options?: RequestInit): Promise<T> {
  if (!API) throw new Error('VITE_API_BASE_URL is not configured for this frontend.')
  const response = await fetch(`${API}${path}`, { ...options, headers: { 'Content-Type': 'application/json', ...options?.headers } })
  if (!response.ok) {
    const detail = await response.json().catch(() => ({}))
    throw new Error(detail.detail ?? `Request failed (${response.status})`)
  }
  return response.json() as Promise<T>
}

function Recenter({ position }: { position: [number, number] }) {
  const map = useMap()
  useEffect(() => { map.setView(position, map.getZoom()) }, [map, position])
  return null
}

function App() {
  const [page, setPage] = useState<Page>('Overview')
  const [menuOpen, setMenuOpen] = useState(false)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [dashboard, setDashboard] = useState<Row | null>(null)
  const [priorities, setPriorities] = useState<Row[]>([])
  const [locations, setLocations] = useState<Row[]>([])
  const [alerts, setAlerts] = useState<Row[]>([])
  const [quality, setQuality] = useState<Row | null>(null)
  const [models, setModels] = useState<Row | null>(null)
  const [metrics, setMetrics] = useState<Row | null>(null)
  const [rfMetrics, setRfMetrics] = useState<Row | null>(null)
  const [trainingHistory, setTrainingHistory] = useState<Row[]>([])
  const [incidentTrend, setIncidentTrend] = useState<Row[]>([])
  const [complaintTrend, setComplaintTrend] = useState<Row[]>([])
  const [forecast, setForecast] = useState<Row | null>(null)
  const [detail, setDetail] = useState<Row | null>(null)
  const [selectedId, setSelectedId] = useState('')
  const [zone, setZone] = useState('')
  const [condition, setCondition] = useState('')
  const [search, setSearch] = useState('')
  const [period, setPeriod] = useState('week')
  const [queuePage, setQueuePage] = useState(0)
  const [sortKey, setSortKey] = useState('priority_score')
  const [sortDirection, setSortDirection] = useState('desc')
  const [queueSearch, setQueueSearch] = useState('')
  const [training, setTraining] = useState(false)
  const [notice, setNotice] = useState('')

  const loadCore = async () => {
    setLoading(true); setError('')
    try {
      const [summary, rank, places, alertData, dataQuality, modelStatus, modelMetrics, history, rfModelMetrics, incidents, complaints, outlook] = await Promise.all([
        api<Row>('/api/dashboard'), api<Row>('/api/priorities?limit=1000'), api<Row>('/api/locations?page_size=1000'),
        api<Row>('/api/alerts'), api<Row>('/api/data-quality'), api<Row>('/api/models/status'), api<Row>('/api/models/metrics'), api<Row>('/api/models/training-history'),
        api<Row>('/model/metrics').catch(() => null),
        api<Row>('/api/incidents/trends?period=week'), api<Row>('/api/complaints/trends?period=week&group_by=category'), api<Row>('/api/forecast'),
      ])
      setDashboard(summary); setPriorities(rank.items); setLocations(places.items); setAlerts(alertData.items); setQuality(dataQuality); setModels(modelStatus); setMetrics(modelMetrics); setTrainingHistory(history.items); setRfMetrics(rfModelMetrics); setIncidentTrend(incidents.items); setComplaintTrend(complaints.items); setForecast(outlook)
    } catch (reason) { setError(reason instanceof Error ? reason.message : 'The CivicLens API is unavailable.') }
    finally { setLoading(false) }
  }

  useEffect(() => { void loadCore() }, [])
  useEffect(() => {
    if (!selectedId) { setDetail(null); return }
    let active = true
    api<Row>(`/api/locations/${selectedId}`).then(value => { if (active) setDetail(value) }).catch(reason => { if (active) setError(reason.message) })
    return () => { active = false }
  }, [selectedId])
  useEffect(() => {
    if (page !== 'Incidents' && page !== 'Complaints') return
    const url = page === 'Incidents' ? `/api/incidents/trends?period=${period}` : `/api/complaints/trends?period=${period}&group_by=category`
    api<Row>(url).then(value => page === 'Incidents' ? setIncidentTrend(value.items) : setComplaintTrend(value.items)).catch(reason => setError(reason.message))
  }, [page, period])

  const mapLocations = useMemo(() => locations.filter(item => (!zone || item.zone === zone) && (!condition || item.road_condition === condition) && (!search || String(item.location_id).toLowerCase().includes(search.toLowerCase()))), [locations, zone, condition, search])
  const orderedRows = useMemo(() => [...priorities].filter(row => !queueSearch || row.location_id.toLowerCase().includes(queueSearch.toLowerCase())).sort((a, b) => {
    const left = a[sortKey], right = b[sortKey]
    return (typeof left === 'string' ? left.localeCompare(right) : Number(left) - Number(right)) * (sortDirection === 'asc' ? 1 : -1)
  }), [priorities, sortKey, sortDirection, queueSearch])
  const mapCenter = useMemo<[number, number]>(() => locations.length ? [locations.reduce((sum, item) => sum + Number(item.latitude), 0) / locations.length, locations.reduce((sum, item) => sum + Number(item.longitude), 0) / locations.length] : [16.48, 80.47], [locations])

  const selectLocation = (id: string) => { setSelectedId(id); setPage('Location Detail') }
  const sort = (key: string) => { setSortDirection(sortKey === key && sortDirection === 'desc' ? 'asc' : 'desc'); setSortKey(key) }
  const startTraining = async () => {
    setTraining(true); setError(''); setNotice('')
    try { await api('/api/models/train', { method: 'POST' }); setNotice('Training started. Results will appear when the run completes.') }
    catch (reason) { setError(reason instanceof Error ? reason.message : 'Training could not start.'); setTraining(false) }
  }
  useEffect(() => {
    if (!training) return
    const timer = window.setInterval(async () => {
      try {
        const [status, result, history] = await Promise.all([api<Row>('/api/models/status'), api<Row>('/api/models/metrics'), api<Row>('/api/models/training-history')])
        setModels(status); setMetrics(result); setTrainingHistory(history.items)
        if (status.training?.status === 'complete' || status.training?.status === 'failed') { setTraining(false); if (status.training.status === 'failed') setError(status.training.error ?? 'Training failed.') }
      } catch (reason) { setTraining(false); setError(reason instanceof Error ? reason.message : 'Training status could not be loaded.') }
    }, 1800)
    return () => window.clearInterval(timer)
  }, [training])

  const title = page === 'Overview' ? 'Operations overview' : page === 'Priority Queue' ? 'Where should we fix first?' : page === 'Location Detail' ? 'Location investigation' : page
  const subtitle = page === 'Overview' ? 'A clear read on reported issues, response patterns, and locations to review.' : page === 'Priority Queue' ? 'A transparent screening queue built from incident, complaint, condition, and context records.' : 'Explore the supplied 2025 synthetic educational records.'

  return <div className="app-shell">
    <aside className={`sidebar ${menuOpen ? 'sidebar-open' : ''}`}>
      <div className="brand"><div className="brand-mark"><Layers3 size={19} /></div><div><strong>CivicLens <span>AI</span></strong><small>OPERATIONS INTELLIGENCE</small></div><button className="icon-button sidebar-close" aria-label="Close menu" onClick={() => setMenuOpen(false)}><X size={18} /></button></div>
      <div className="workspace-switch"><div className="workspace-symbol">C</div><div><small>WORKSPACE</small><strong>Central operations</strong></div><ChevronDown size={15} /></div>
      {['WORKSPACE', 'MONITOR', 'ANALYTICS', 'SYSTEM'].map(group => <div className="nav-group" key={group}><span className="nav-label">{group}</span>{navigation.filter(item => item.group === group).map(item => <button key={item.name} onClick={() => { setPage(item.name); setMenuOpen(false) }} className={`nav-item ${page === item.name ? 'active' : ''}`}><item.icon size={17} strokeWidth={1.8} /><span>{item.name}</span>{item.name === 'Alerts' && alerts.length > 0 && <b className="nav-count">{alerts.length}</b>}</button>)}</div>)}
      <div className="sidebar-bottom"><div className="data-mark"><span className="pulse-dot"/> LOCAL DATASET <span>2025</span></div><div className="user-chip"><div className="avatar">CO</div><div><strong>City operations</strong><small>Prototype workspace</small></div><ChevronDown size={14}/></div></div>
    </aside>
    {menuOpen && <button className="mobile-scrim" aria-label="Close navigation" onClick={() => setMenuOpen(false)} />}
    <main className="main-shell">
      <header className="topbar"><button className="icon-button mobile-menu" aria-label="Open navigation" onClick={() => setMenuOpen(true)}><Menu size={19}/></button><div className="crumb"><span>Operations</span><ChevronRight size={14}/><strong>{page}</strong></div><div className="topbar-right"><span className="offline-indicator"><i/> HISTORICAL DATA</span><button className="icon-button" aria-label="Refresh data" title="Refresh data" onClick={() => void loadCore()}><RefreshCw size={17}/></button><div className="top-date"><span>RECORD WINDOW</span><strong>{dashboard?.incident_date_range?.[0] ?? '—'} <span>to</span> {dashboard?.incident_date_range?.[1] ?? '—'}</strong></div></div></header>
      <section className="page-content">
        <div className="page-heading"><div><div className="eyebrow"><span className="eyebrow-rule"/> CIVIC OPERATIONS / {page.toUpperCase()}</div><h1>{title}</h1><p>{subtitle}</p></div><div className="heading-actions"><button className="button button-outline" onClick={() => setPage('Priority Queue')}><ClipboardList size={16}/> Review queue <ArrowRight size={15}/></button></div></div>
        <div className="synthetic-banner"><ShieldAlert size={17}/><span><strong>Synthetic educational data.</strong> Coordinates are simulated, records are historical, and model outputs are not real-world civic safety assessments.</span><button aria-label="Dismiss disclaimer" title="Dismiss disclaimer" onClick={event => event.currentTarget.parentElement?.remove()}><X size={15}/></button></div>
        {error && <div className="notice notice-error" role="alert"><AlertTriangle size={17}/><span><strong>Connection or data error</strong>{error}</span><button onClick={() => void loadCore()}>Retry</button></div>}
        {notice && <div className="notice notice-success" role="status"><Activity size={16}/>{notice}<button aria-label="Dismiss" onClick={() => setNotice('')}><X size={15}/></button></div>}
        {loading && !dashboard ? <div className="loading-panel"><span className="spinner"/>Connecting to the local CivicLens API…</div> : !error && dashboard && <>
          {page === 'Overview' && <Overview dashboard={dashboard} priorities={priorities} incidents={incidentTrend} complaints={complaintTrend} alerts={alerts} onSelect={selectLocation} onNavigate={setPage}/>}
          {page === 'Live Map' && <MapView locations={mapLocations} priorities={priorities} center={mapCenter} zone={zone} condition={condition} search={search} setZone={setZone} setCondition={setCondition} setSearch={setSearch} selectedId={selectedId} onSelect={setSelectedId} onOpen={setPage} detail={detail}/>}
          {page === 'Priority Queue' && <Queue rows={orderedRows} search={queueSearch} setSearch={setQueueSearch} page={queuePage} setPage={setQueuePage} sortKey={sortKey} sort={sort} selectedId={selectedId} onSelect={selectLocation}/>}
          {page === 'Incidents' && <Trends kind="incident" rows={incidentTrend} period={period} setPeriod={setPeriod} incidents={priorities}/>}
          {page === 'Complaints' && <Trends kind="complaint" rows={complaintTrend} period={period} setPeriod={setPeriod} incidents={priorities}/>}
          {page === 'Forecasts' && <ForecastView data={forecast}/>}
          {page === 'Location Detail' && detail && <LocationDetail detail={detail} modelMetrics={metrics} onMap={() => setPage('Live Map')} onQueue={() => setPage('Priority Queue')}/>}
          {page === 'Location Detail' && !detail && <div className="empty-state">Choose a location from the map or priority queue.</div>}
          {page === 'Model Lab' && <><ModelLab metrics={metrics} status={models} history={trainingHistory.map(row=>({...row,training:row.training_mse,validation:row.validation_mse}))} training={training} onTrain={() => void startTraining()}/><RegressionMetricStrip report={metrics?.manual_linear_regression}/><RandomForestMetrics metrics={rfMetrics}/><ModelLabRuntime status={models} history={trainingHistory} report={metrics?.manual_linear_regression} cleaning={metrics?.data_cleaning}/><ModelPredictionForm training={training}/></>}
          {page === 'Alerts' && <AlertView alerts={alerts} onSelect={selectLocation}/>}
          {page === 'Settings' && <Settings quality={quality} status={models} onRefresh={async () => { try { const result = await api<Row>('/api/data/refresh', {method:'POST'}); setQuality(result.report); setNotice('Dataset aggregates refreshed from the supplied CSV files.') } catch(reason) { setError(reason instanceof Error ? reason.message : 'Refresh failed.') } }} onTrain={() => void startTraining()}/>}
        </>}
        <footer className="page-footer"><span>CIVICLENS AI <b>·</b> DECISION SUPPORT PROTOTYPE</span><span>Evidence first. Human review always.</span></footer>
      </section>
    </main>
  </div>
}

function Metric({ label, value, detail, icon: Icon, tone, trend }: { label: string; value: string; detail: string; icon: typeof Activity; tone: string; trend?: number }) {
  return <article className="metric-card"><div className="metric-top"><span>{label}</span><i className={`metric-icon ${tone}`}><Icon size={17}/></i></div><strong className="metric-value">{value}</strong><div className="metric-detail">{trend !== undefined && <span className={trend > 0 ? 'trend-up' : 'trend-down'}>{trend > 0 ? <ArrowUpRight size={13}/> : <ArrowDownRight size={13}/>} {fmt(Math.abs(trend), 1)}%</span>}{detail}</div></article>
}

function Overview({ dashboard, priorities, incidents, complaints, alerts, onSelect, onNavigate }: { dashboard: Row; priorities: Row[]; incidents: Row[]; complaints: Row[]; alerts: Row[]; onSelect: (id: string) => void; onNavigate: (page: Page) => void }) {
  const categoryCounts = Object.entries(complaints.reduce((acc: Record<string, number>, row) => { acc[row.category] = (acc[row.category] ?? 0) + row.count; return acc }, {})).map(([name, count]) => ({name, count}))
  return <>
    <div className="section-kicker"><span>01</span> SERVICE PICTURE <small>Calculated from the supplied records</small></div>
    <div className="metric-grid">
      <Metric label="Monitored locations" value={fmt(dashboard.locations)} detail="simulated points" icon={MapPin} tone="tone-teal"/>
      <Metric label="Recorded incidents" value={fmt(dashboard.incidents)} detail="Jan–Dec 2025" icon={TrafficCone} tone="tone-ink" trend={dashboard.recent_trend.change_percent}/>
      <Metric label="Public complaints" value={fmt(dashboard.complaints)} detail="historical submissions" icon={Activity} tone="tone-amber"/>
      <Metric label="Unresolved records" value={fmt(dashboard.open_incidents + dashboard.open_complaints)} detail={`${fmt(dashboard.open_incidents)} incidents · ${fmt(dashboard.open_complaints)} complaints`} icon={Clock3} tone="tone-rose"/>
    </div>
    <div className="metric-grid metric-grid-secondary">
      <Metric label="Mean resolved incident" value={`${fmt(dashboard.average_resolution_hours, 1)}h`} detail="resolved records only" icon={Clock3} tone="tone-ink"/>
      <Metric label="Priority review" value={fmt(dashboard.high_priority_locations)} detail="score ≥ 75 / 100" icon={Gauge} tone="tone-amber"/>
      <Metric label="Repeated locations" value={fmt(dashboard.repeated_incident_locations)} detail="3+ incident records" icon={Layers3} tone="tone-teal"/>
      <Metric label="Review signals" value={fmt(alerts.length)} detail="heuristic alert checks" icon={Bell} tone="tone-rose"/>
    </div>
    <div className="overview-grid">
      <section className="panel trend-panel"><div className="panel-heading"><div><div className="panel-eyebrow">INCIDENT ACTIVITY</div><h2>Reported volume</h2></div><button className="text-button" onClick={() => onNavigate('Incidents')}>View trends <ArrowRight size={14}/></button></div><div className="chart-legend"><span><i className="legend-teal"/> Incidents by week</span><span className="subtle-tag">52-week record</span></div><div className="chart-area"><ResponsiveContainer width="100%" height="100%"><AreaChart data={incidents}><defs><linearGradient id="incidentFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#287a70" stopOpacity={0.2}/><stop offset="95%" stopColor="#287a70" stopOpacity={0.01}/></linearGradient></defs><CartesianGrid vertical={false} stroke="#e9e8e3" strokeDasharray="3 5"/><XAxis dataKey="date" tickFormatter={shortDate} tickLine={false} axisLine={false} minTickGap={30}/><YAxis tickLine={false} axisLine={false} width={35}/><Tooltip labelFormatter={value=>shortDate(String(value))} contentStyle={{borderRadius:6,border:'1px solid #e5e3dd',fontSize:12}}/><Area type="monotone" dataKey="count" name="Incidents" stroke="#287a70" strokeWidth={2} fill="url(#incidentFill)"/></AreaChart></ResponsiveContainer></div><div className="trend-foot"><span>Recent 30 days <strong>{fmt(dashboard.recent_trend.last_30_days)}</strong></span><span>Prior 30 days <strong>{fmt(dashboard.recent_trend.prior_30_days)}</strong></span><span className={dashboard.recent_trend.change_percent > 0 ? 'text-rose' : 'text-teal'}>{dashboard.recent_trend.change_percent > 0 ? '+' : ''}{fmt(dashboard.recent_trend.change_percent,1)}% period change</span></div></section>
      <section className="panel queue-preview"><div className="panel-heading"><div><div className="panel-eyebrow">INVESTIGATION QUEUE</div><h2>Locations to review</h2></div><button className="text-button" onClick={() => onNavigate('Priority Queue')}>Full queue <ArrowRight size={14}/></button></div><div className="mini-queue">{priorities.slice(0,5).map((row,index)=><button className="mini-row" key={row.location_id} onClick={() => onSelect(row.location_id)}><span className="mini-rank">{String(index+1).padStart(2,'0')}</span><span className="mini-location"><strong>{row.location_id}</strong><small>{row.zone} <i/> {row.road_condition} condition</small></span><span className="mini-score" style={{color:roadColor(row.priority_score)}}>{fmt(row.priority_score)}<small>score</small></span><ChevronRight size={15} className="mini-chevron"/></button>)}</div><div className="queue-foot"><span><i className="status-dot status-strong"/> Priority heuristic</span><span>Not a probability of harm</span></div></section>
    </div>
    <div className="overview-bottom"><section className="panel category-panel"><div className="panel-heading"><div><div className="panel-eyebrow">PUBLIC VOICE</div><h2>Complaint categories</h2></div><button className="text-button" onClick={() => onNavigate('Complaints')}>Explore <ArrowRight size={14}/></button></div><div className="category-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={categoryCounts} layout="vertical" margin={{left:8,right:8}}><XAxis type="number" hide/><YAxis type="category" dataKey="name" width={104} tickLine={false} axisLine={false} tick={{fontSize:11,fill:'#6f7773'}}/><Tooltip contentStyle={{borderRadius:6,fontSize:12}}/><Bar dataKey="count" name="Complaints" fill="#c28e43" radius={[0,3,3,0]} barSize={13}/></BarChart></ResponsiveContainer></div></section>
      <section className="panel alert-preview"><div className="panel-heading"><div><div className="panel-eyebrow">NEEDS A LOOK</div><h2>Recent signals</h2></div><button className="text-button" onClick={() => onNavigate('Alerts')}>All alerts <ArrowRight size={14}/></button></div>{alerts.slice(0,3).map(alert=><button className="alert-line" key={alert.id} onClick={() => onSelect(alert.location_id)}><span className={`alert-mark ${alert.severity === 'context' ? 'context-mark' : ''}`}><AlertTriangle size={15}/></span><span><strong>{alert.type}</strong><small>{alert.location_id} · {alert.reason}</small></span><ChevronRight size={15}/></button>)}{!alerts.length && <div className="empty-small">No alert checks fired for this dataset.</div>}</section></div>
  </>
}

function MapView({ locations, priorities, center, zone, condition, search, setZone, setCondition, setSearch, selectedId, onSelect, onOpen, detail }: { locations: Row[]; priorities: Row[]; center: [number,number]; zone: string; condition: string; search: string; setZone: (value:string)=>void; setCondition:(value:string)=>void; setSearch:(value:string)=>void; selectedId:string; onSelect:(id:string)=>void; onOpen:(page:Page)=>void; detail:Row|null }) {
  const scoreMap = useMemo(() => new Map(priorities.map(row => [row.location_id, row])), [priorities])
  const selected = locations.find(row => row.location_id === selectedId) ?? priorities.find(row => row.location_id === selectedId)
  const zones = [...new Set(locations.map(row=>row.zone))].sort()
  return <div className="map-workspace"><div className="map-toolbar"><label className="search-field"><Search size={16}/><input aria-label="Search location ID" placeholder="Search location ID" value={search} onChange={event=>setSearch(event.target.value)}/><kbd>⌕</kbd></label><label className="filter-control"><SlidersHorizontal size={15}/><select aria-label="Filter zone" value={zone} onChange={event=>setZone(event.target.value)}><option value="">All zones</option>{zones.map(value=><option key={value}>{value}</option>)}</select></label><label className="filter-control"><select aria-label="Filter road condition" value={condition} onChange={event=>setCondition(event.target.value)}><option value="">All conditions</option>{['Good','Fair','Poor','Critical'].map(value=><option key={value}>{value}</option>)}</select></label><span className="result-count">{fmt(locations.length)} points</span></div><div className="map-layout"><section className="map-frame"><MapContainer center={center} zoom={11} scrollWheelZoom className="leaflet-map"><Recenter position={center}/><TileLayer attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>' url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"/>{locations.map(row=>{const rank=scoreMap.get(row.location_id); const score=rank?.priority_score??0;return <CircleMarker key={row.location_id} center={[Number(row.latitude),Number(row.longitude)]} radius={selectedId===row.location_id?8:5} pathOptions={{color:roadColor(score),fillColor:roadColor(score),fillOpacity:.82,weight:selectedId===row.location_id?3:1}} eventHandlers={{click:()=>onSelect(row.location_id)}}><Popup><strong>{row.location_id}</strong><br/>{row.zone} · {row.road_condition}<br/>Screening score {fmt(score)}</Popup></CircleMarker>})}</MapContainer><div className="map-legend"><strong>SCREENING SCORE</strong><span><i className="legend-low"/> Under 55</span><span><i className="legend-mid"/> 55–74</span><span><i className="legend-high"/> 75+</span></div><div className="map-disclaimer">Simulated coordinates · not real streets</div></section><aside className="map-sidepanel"><div className="map-side-head"><div><span className="panel-eyebrow">RANKED LOCATIONS</span><strong>Review shortlist</strong></div><span className="result-count">{locations.length}</span></div><div className="map-rank-list">{[...locations].sort((a,b)=>(scoreMap.get(b.location_id)?.priority_score??0)-(scoreMap.get(a.location_id)?.priority_score??0)).slice(0,70).map((row,index)=>{const score=scoreMap.get(row.location_id)?.priority_score??0;return <button key={row.location_id} className={`map-rank-row ${selectedId===row.location_id?'selected':''}`} onClick={()=>onSelect(row.location_id)}><span className="map-rank">{String(index+1).padStart(2,'0')}</span><span className="map-rank-name"><strong>{row.location_id}</strong><small>{row.zone} · {row.road_condition}</small></span><b style={{color:roadColor(score)}}>{fmt(score)}</b></button>})}{!locations.length&&<div className="empty-small">No locations match these filters.</div>}</div>{selected&&<div className="location-card"><button className="location-card-close icon-button" aria-label="Clear selected location" onClick={()=>onSelect('')}><X size={15}/></button><span className="panel-eyebrow">SELECTED LOCATION</span><h3>{selected.location_id}</h3><p>{selected.zone} · {selected.road_type} · {selected.road_condition}</p><div className="location-card-stats"><span><strong>{fmt(detail?.priority?.incident_count??selected.incident_count)}</strong> incidents</span><span><strong>{fmt(detail?.priority?.open_complaints??selected.open_complaints)}</strong> open complaints</span><span><strong>{fmt(scoreMap.get(selected.location_id)?.priority_score??0)}</strong> score</span></div><button className="button button-dark full-button" onClick={()=>onOpen('Priority Queue')}>Open investigation <ArrowRight size={15}/></button></div>}</aside></div></div>
}

function Queue({ rows, search, setSearch, page, setPage, sortKey, sort, selectedId, onSelect }: { rows:Row[];search:string;setSearch:(value:string)=>void;page:number;setPage:(n:number)=>void;sortKey:string;sort:(key:string)=>void;selectedId:string;onSelect:(id:string)=>void }) {
  const pageSize=20, maxPage=Math.max(0,Math.ceil(rows.length/pageSize)-1), shown=rows.slice(page*pageSize,(page+1)*pageSize)
  const columns=[['rank','#'],['location_id','Location'],['zone','Zone'],['road_condition','Road'],['incident_count','Incidents'],['severe_incidents','Severe'],['injuries','Injuries'],['open_complaints','Open complaints'],['average_resolution_hours','Mean hours'],['priority_score','Score']]
  return <section className="panel queue-table-panel"><div className="queue-controls"><div><div className="panel-eyebrow">1000 LOCATIONS · EVIDENCE-BASED REVIEW</div><h2>Priority queue</h2></div><div className="queue-tools"><label className="search-field queue-search"><Search size={15}/><input placeholder="Find location" aria-label="Find location in queue" value={search} onChange={event=>{setSearch(event.target.value);setPage(0)}}/><kbd>⌕</kbd></label><button className="button button-outline" onClick={()=>sort(sortKey)}><SlidersHorizontal size={15}/> Sort</button></div></div><div className="formula-strip"><CircleHelp size={15}/><span><strong>Screening heuristic</strong> · Percentile-normalized evidence components, weighted by the published formula. Not a probability of harm.</span><span className="formula-link">Inspect evidence on each row →</span></div><div className="table-scroll"><table className="priority-table"><thead><tr>{columns.map(([key,label])=><th key={key} className={key==='rank'||key==='location_id'||key==='zone'||key==='road_condition'?'align-left':''}><button onClick={()=>sort(key)}>{label}{sortKey===key&&<span className="sort-indicator">↕</span>}</button></th>)}<th>Evidence</th><th>Next step</th></tr></thead><tbody>{shown.map(row=><tr key={row.location_id} className={selectedId===row.location_id?'row-selected':''} onClick={()=>onSelect(row.location_id)} tabIndex={0} onKeyDown={event=>event.key==='Enter'&&onSelect(row.location_id)}><td className="rank-cell">{String(row.rank).padStart(2,'0')}</td><td><strong className="mono-id">{row.location_id}</strong></td><td>{row.zone}</td><td><span className={`condition-pill condition-${String(row.road_condition).toLowerCase()}`}>{row.road_condition}</span></td><td>{fmt(row.incident_count)}</td><td>{fmt(row.severe_incidents)}</td><td>{fmt(row.injuries)}</td><td>{fmt(row.open_complaints)}</td><td>{fmt(row.average_resolution_hours,1)}</td><td><span className="score-cell" style={{color:roadColor(row.priority_score)}}>{fmt(row.priority_score)}</span></td><td><span className={`evidence-pill evidence-${row.evidence_strength.toLowerCase()}`}>{row.evidence_strength}</span></td><td className="next-step-cell">{row.recommendation}</td></tr>)}</tbody></table>{!shown.length&&<div className="empty-state">No locations in this view.</div>}</div><div className="pagination"><span>Showing <strong>{rows.length? page*pageSize+1:0}–{Math.min((page+1)*pageSize,rows.length)}</strong> of <strong>{fmt(rows.length)}</strong> locations</span><div><button className="icon-button" aria-label="Previous page" disabled={page===0} onClick={()=>setPage(Math.max(0,page-1))}><ChevronLeft size={17}/></button><span>Page {page+1} / {maxPage+1}</span><button className="icon-button" aria-label="Next page" disabled={page>=maxPage} onClick={()=>setPage(Math.min(maxPage,page+1))}><ChevronRight size={17}/></button></div></div></section>
}

function Trends({kind,rows,period,setPeriod,incidents}:{kind:'incident'|'complaint';rows:Row[];period:string;setPeriod:(value:string)=>void;incidents:Row[]}) {
  const isIncident=kind==='incident'
  const title=isIncident?'Incident monitoring':'Complaint monitoring'
  const summary=isIncident?`${fmt(incidents.reduce((sum,row)=>sum+row.incident_count,0))} incident records across all locations`:'Category and timing trends from historical complaints'
  const distribution=isIncident?['Low','Medium','High','Critical'].map(name=>({name,count:incidents.reduce((sum,row)=>sum+(row.severity_distribution?.[name]??0),0)})):rows.reduce((acc:Row[],row)=>{const found=acc.find(item=>item.category===row.category);if(found)found.count+=row.count;else acc.push({category:row.category,count:row.count});return acc},[])
  const openCount=incidents.reduce((sum,row)=>sum+(isIncident?row.unresolved_incidents:row.open_complaints),0)
  return <><div className="monitor-summary"><section className="panel monitor-intro"><span className="panel-eyebrow">HISTORICAL MONITORING</span><h2>{title}</h2><p>{summary}</p><div className="period-switch">{['day','week','month'].map(value=><button key={value} className={period===value?'selected':''} onClick={()=>setPeriod(value)}>{value}</button>)}</div></section><Metric label={isIncident?'Unresolved incidents':'Open complaints'} value={fmt(openCount)} detail="across locations" icon={Clock3} tone="tone-rose"/><Metric label={isIncident?'Severe records':'Complaint categories'} value={isIncident?fmt(incidents.reduce((sum,row)=>sum+row.severe_incidents,0)):fmt(distribution.length)} detail={isIncident?'high or critical severity':'represented in the data'} icon={isIncident?ShieldAlert:Activity} tone="tone-amber"/></div><div className="overview-grid monitor-charts"><section className="panel"><div className="panel-heading"><div><div className="panel-eyebrow">VOLUME OVER TIME</div><h2>{isIncident?'Incident':'Complaint'} records per {period}</h2></div><span className="subtle-tag">Not live</span></div><div className="chart-area chart-area-tall"><ResponsiveContainer width="100%" height="100%">{isIncident?<LineChart data={rows}><CartesianGrid vertical={false} stroke="#e9e8e3" strokeDasharray="3 5"/><XAxis dataKey="date" tickFormatter={shortDate} tickLine={false} axisLine={false} minTickGap={30}/><YAxis tickLine={false} axisLine={false} width={35}/><Tooltip labelFormatter={value=>shortDate(String(value))}/><Line type="monotone" dataKey="count" name="Incidents" stroke="#287a70" strokeWidth={2} dot={false}/></LineChart>:<AreaChart data={rows}><CartesianGrid vertical={false} stroke="#e9e8e3" strokeDasharray="3 5"/><XAxis dataKey="date" tickFormatter={shortDate} tickLine={false} axisLine={false} minTickGap={30}/><YAxis tickLine={false} axisLine={false} width={35}/><Tooltip labelFormatter={value=>shortDate(String(value))}/><Area type="monotone" dataKey="count" name="Complaints" stroke="#c28e43" fill="#c28e43" fillOpacity={0.12}/></AreaChart>}</ResponsiveContainer></div><small className="chart-footnote">Date range from the dataset; periods without a record are not presented as zero.</small></section><section className="panel"><div className="panel-heading"><div><div className="panel-eyebrow">RECORD MIX</div><h2>{isIncident?'Severity':'Category'} distribution</h2></div></div><div className="category-chart category-chart-large"><ResponsiveContainer width="100%" height="100%"><BarChart data={distribution} layout="vertical" margin={{left:8,right:20}}><XAxis type="number" hide/><YAxis type="category" dataKey="name" width={122} tickLine={false} axisLine={false} tick={{fontSize:11,fill:'#6f7773'}}/><Tooltip/><Bar dataKey="count" name="Records" radius={[0,3,3,0]} barSize={17}>{distribution.map((_:Row,index:number)=><Cell key={index} fill={['#287a70','#c28e43','#57777a','#ba5142','#6d8276','#9b7655'][index%6]}/>)}</Bar></BarChart></ResponsiveContainer></div></section></div><div className="notice notice-neutral"><CircleHelp size={16}/><span><strong>Historical records only.</strong> One synthetic calendar year does not establish a live trend, causal pattern, or forecast certainty.</span></div></>
}

function ModelLab({metrics,status,history,training,onTrain}:{metrics:Row|null;status:Row|null;history:Row[];training:boolean;onTrain:()=>void}) {
  const report=metrics?.manual_linear_regression
  const model=report?.manual_linear_regression?.metrics
  const baseline=report?.training_median_baseline?.metrics
  return <><div className="model-summary"><section className="panel model-feature"><div className="model-feature-top"><span className="model-symbol"><Sparkles size={20}/></span><span className="evidence-pill evidence-moderate">FROM SCRATCH</span></div><span className="panel-eyebrow">INCIDENT RESOLUTION · HOURS</span><h2>Linear regression, built in NumPy</h2><p>One-hot categorical features, standardized numeric inputs and target, an explicit intercept, and full-batch gradient descent. No Scikit-learn regression estimator in the training algorithm.</p><div className="model-meta"><span><small>Training set</small><strong>{fmt(report?.data_split?.train_records)} records</strong></span><span><small>Validation set</small><strong>{fmt(report?.data_split?.validation_records)} records</strong></span><span><small>Test set</small><strong>{fmt(report?.data_split?.test_records)} records</strong></span><span><small>Last trained</small><strong>{report?.trained_at?new Date(report.trained_at).toLocaleString():'Not trained'}</strong></span></div><button className="button button-dark" onClick={onTrain} disabled={training}><RefreshCw size={15} className={training?'spin':''}/>{training?'Training in progress':'Retrain model'}</button>{training&&<div className="training-state"><span className="spinner spinner-small"/> Training runs in the background; status updates when the run finishes.</div>}</section><section className="panel model-readout"><div className="panel-heading"><div><div className="panel-eyebrow">HELD-OUT PERFORMANCE</div><h2>Measured test metrics</h2></div><CircleHelp size={17} className="help-icon"/></div>{model?<><div className="metric-comparison"><div><span>MAE</span><strong>{fmt(model.mae,2)} <small>h</small></strong><small>baseline {fmt(baseline?.mae,2)} h</small></div><div><span>RMSE</span><strong>{fmt(model.rmse,2)} <small>h</small></strong><small>baseline {fmt(baseline?.rmse,2)} h</small></div><div><span>R²</span><strong>{fmt(model.r2,3)}</strong><small>baseline {fmt(baseline?.r2,3)}</small></div></div><div className="model-result-callout"><AlertTriangle size={16}/><span>{model.mae>baseline?.mae?'MAE is worse than the median baseline. ':'The result remains a weak estimate. '}R² is {model.r2<0?'below zero, so the model does not explain test-set variation reliably.':'measured on the same chronological holdout.'}</span></div></>:<div className="empty-small">Run training to generate evaluation metrics.</div>}<div className="model-diagnostic"><strong>Model comparison</strong><span>Random Forest MAE {fmt(report?.random_forest_comparison?.metrics?.mae,2)} h</span><span>Training-median baseline MAE {fmt(baseline?.mae,2)} h</span></div></section></div><div className="overview-grid model-charts"><section className="panel"><div className="panel-heading"><div><div className="panel-eyebrow">OPTIMIZATION TRACE</div><h2>Training and validation loss</h2></div><span className="subtle-tag">{fmt(report?.manual_linear_regression?.epochs_run)} epochs</span></div><div className="chart-area chart-area-tall"><ResponsiveContainer width="100%" height="100%"><LineChart data={history}><CartesianGrid vertical={false} stroke="#e9e8e3" strokeDasharray="3 5"/><XAxis dataKey="epoch" tickLine={false} axisLine={false}/><YAxis tickLine={false} axisLine={false} width={48}/><Tooltip/><Line dataKey="training" name="Training MSE" stroke="#287a70" dot={false} strokeWidth={2}/><Line dataKey="validation" name="Validation MSE" stroke="#c28e43" dot={false} strokeWidth={1.7}/></LineChart></ResponsiveContainer></div><div className="chart-legend"><span><i className="legend-teal"/> Training loss</span><span><i className="legend-amber"/> Validation loss</span></div></section><section className="panel"><div className="panel-heading"><div><div className="panel-eyebrow">EVALUATION DESIGN</div><h2>How the test was kept honest</h2></div></div><div className="evidence-list"><div><b>01</b><span><strong>Chronological split</strong><small>70% train · 15% validation · 15% test, ordered by timestamp.</small></span></div><div><b>02</b><span><strong>Resolved targets only</strong><small>{fmt(report?.data_split?.excluded_records)} rows excluded: unresolved status or invalid duration/timestamp.</small></span></div><div><b>03</b><span><strong>Baseline retained</strong><small>Every test metric is compared with the training-set median prediction.</small></span></div><div><b>04</b><span><strong>Location context joined</strong><small>Features use location attributes; location IDs are not model inputs.</small></span></div></div><div className="model-limitations">Metadata cannot capture work-order complexity, crew availability, parts, or weather. Prediction is an estimate, never a service commitment.</div></section></div><div className="secondary-models"><span><strong>Other measured diagnostics</strong> · Existing complaint models and classifier</span><span>{status?.metrics?.complaint_category?.macro_f1!==undefined?`Complaint metadata classifier macro-F1 ${fmt(status.metrics.complaint_category.macro_f1,3)}; text is not available.`:'Model status unavailable.'}</span></div></>
}

function RegressionMetricStrip({report}:{report:Row|null}) {
  const metrics=report?.manual_linear_regression?.metrics
  const baseline=report?.training_median_baseline?.metrics
  return <section className="panel regression-metric-strip"><div className="panel-eyebrow">SAVED CHRONOLOGICAL TEST RESULTS</div><div><span>MSE <strong>{fmt(metrics?.mse,2)}</strong><small>median {fmt(baseline?.mse,2)}</small></span><span>MAE <strong>{fmt(metrics?.mae,2)} h</strong><small>median {fmt(baseline?.mae,2)} h</small></span><span>RMSE <strong>{fmt(metrics?.rmse,2)} h</strong><small>median {fmt(baseline?.rmse,2)} h</small></span><span>R² <strong>{fmt(metrics?.r2,4)}</strong><small>median {fmt(baseline?.r2,4)}</small></span></div><p>Scratch model {metrics&&baseline?(metrics.mae<baseline.mae?'beats':'does not beat'):'comparison unavailable'} the median on MAE; R² {metrics?(metrics.r2<0?'is below zero':'is '+fmt(metrics.r2,4)):'is unavailable'}. API estimate follows the measured minimum-MAE selection.</p></section>
}

function ModelLabRuntime({status,history,report,cleaning}:{status:Row|null;history:Row[];report:Row|null;cleaning:Row|null}) {
  const latest=history.at(-1)
  return <div className="overview-grid model-runtime-grid"><section className="panel model-feature"><div className="panel-heading"><div><div className="panel-eyebrow">TRAINING JOB</div><h2>Actual run progress</h2></div><span className="subtle-tag">{status?.training?.status??'unknown'}</span></div><div className="training-progress-summary"><span><small>Epochs completed</small><strong>{fmt(status?.training?.epochs_completed??history.length)}</strong></span><span><small>Training MSE</small><strong>{fmt(latest?.training_mse??report?.manual_linear_regression?.final_training_mse,2)} h²</strong></span><span><small>Validation MSE</small><strong>{fmt(latest?.validation_mse??report?.manual_linear_regression?.final_validation_mse,2)} h²</strong></span><span><small>Training duration</small><strong>{fmt(report?.training_duration_seconds,2)} s</strong></span></div><p>Progress values come from each completed optimizer epoch. No estimated percentages are shown.</p></section><section className="panel model-feature"><div className="panel-heading"><div><div className="panel-eyebrow">CLEANING AND EXCLUSIONS</div><h2>Training data audit</h2></div><Database size={17} className="help-icon"/></div><div className="training-progress-summary"><span><small>Original incident records</small><strong>{fmt(cleaning?.incident_resolution_training?.original_records)}</strong></span><span><small>Resolved usable records</small><strong>{fmt(cleaning?.incident_resolution_training?.usable_records)}</strong></span><span><small>Excluded with reasons</small><strong>{fmt(cleaning?.incident_resolution_training?.excluded_records)}</strong></span><span><small>Outliers flagged, retained</small><strong>{fmt(cleaning?.incident_resolution_training?.target_outlier_check?.flagged_records)}</strong></span></div><p>Missing values are handled using encoder/imputation parameters fitted on training rows. Outlier checks are reported, not used to silently remove records.</p></section></div>
}

function RandomForestMetrics({metrics}:{metrics:Row|null}) {
  const test=metrics?.held_out_test
  const cv=metrics?.cross_validation
  const importance=Object.entries(metrics?.feature_importance?.by_source_feature??{}).map(([feature,value])=>({feature,value:Number(value)})).sort((a,b)=>b.value-a.value).slice(0,7)
  const predictionSpread=metrics?.prediction_distribution
  const targetSpread=metrics?.target_distribution
  return <section className="panel model-feature rf-metrics-panel"><div className="panel-heading"><div><div className="panel-eyebrow">RANDOM FOREST REGRESSION</div><h2>{metrics?.model_name??'Random Forest model'}</h2></div><span className="subtle-tag">{fmt(metrics?.training_dataset_size)} eligible records</span></div>{metrics?<><p className="rf-split-note">Held-out test metrics and training-only temporal cross-validation are reported separately.</p><div className="rf-metric-grid"><div><small>Test MAE</small><strong>{fmt(test?.random_forest?.mae,2)} h</strong></div><div><small>Test RMSE</small><strong>{fmt(test?.random_forest?.rmse,2)} h</strong></div><div><small>Test R²</small><strong>{fmt(test?.random_forest?.r2,3)}</strong></div><div><small>3-fold temporal CV MAE</small><strong>{fmt(cv?.best_mean_cv_mae,2)} h</strong></div></div><div className="rf-comparison">Median baseline test MAE: <strong>{fmt(test?.median_baseline?.mae,2)} h</strong>. {metrics.comparison?.random_forest_beats_median_on_mae?'Random Forest had lower test MAE.':'Random Forest did not beat the median baseline on test MAE.'}</div><div className="rf-audit-grid"><div><strong>Largest grouped impurity importances</strong>{importance.map(item=><span key={item.feature}>{item.feature.replaceAll('_',' ')} <b>{(item.value*100).toFixed(1)}%</b></span>)}<small>Descriptive, not causal; high importance does not prove a field drives resolution time.</small></div><div><strong>Held-out distribution</strong><span>Actual median <b>{fmt(targetSpread?.quantiles?.['0.5'],1)} h</b></span><span>RF median <b>{fmt(predictionSpread?.quantiles?.['0.5'],1)} h</b></span><span>RF 5th–95th <b>{fmt(predictionSpread?.quantiles?.['0.05'],1)}–{fmt(predictionSpread?.quantiles?.['0.95'],1)} h</b></span><small>Predictions are concentrated relative to observed durations. Injury training support: {fmt(metrics.features?.training_numeric_support?.injuries?.min)}–{fmt(metrics.features?.training_numeric_support?.injuries?.max)}.</small></div></div><small className="rf-model-date">Trained {metrics.training_timestamp?new Date(metrics.training_timestamp).toLocaleString():'—'} · test period {metrics.split?.test_start} to {metrics.split?.test_end}</small></>:<div className="empty-small">Random Forest metrics are unavailable. Train the model from the backend before using RF predictions.</div>}</section>
}

function ModelPredictionForm({training}:{training:boolean}) {
  const [form,setForm]=useState({location_id:'L0001',incident_type:'Pothole',severity:'Medium',reported_by:'Citizen',reported_injuries:0})
  const [result,setResult]=useState<Row|null>(null)
  const [error,setError]=useState('')
  const [busy,setBusy]=useState(false)
  const requiresUrgentReview=form.severity==='Critical'||(form.severity==='High'&&form.reported_injuries>0)||(form.incident_type==='Collision'&&form.reported_injuries>=5)
  const submit=async(event:FormEvent<HTMLFormElement>)=>{
    event.preventDefault();setBusy(true);setError('');setResult(null)
    try{setResult(await api<Row>('/predict',{method:'POST',body:JSON.stringify(form)}))}
    catch(reason){setError(reason instanceof Error?reason.message:'Random Forest prediction failed. Check the API connection and input values.')}
    finally{setBusy(false)}
  }
  const formatHours=(hours:number)=>{let whole=Math.floor(hours),minutes=Math.round((hours-whole)*60);if(minutes===60){whole+=1;minutes=0}return `${whole} hours ${minutes} minutes`}
  return <section className="panel model-feature prediction-panel">
    <div className="panel-heading"><div><div className="panel-eyebrow">RANDOM FOREST INFERENCE</div><h2>Estimate incident resolution time</h2></div><span className="subtle-tag">Live API</span></div>
    <form className="prediction-form" onSubmit={submit}>
      <label>Location ID<input required maxLength={40} value={form.location_id} onChange={event=>setForm({...form,location_id:event.target.value})}/></label>
      <label>Incident type<select value={form.incident_type} onChange={event=>setForm({...form,incident_type:event.target.value})}>{['Pothole','Signal failure','Streetlight outage','Blocked drain','Collision','Flooding'].map(value=><option key={value}>{value}</option>)}</select></label>
      <label>Severity<select value={form.severity} onChange={event=>setForm({...form,severity:event.target.value})}>{['Low','Medium','High','Critical'].map(value=><option key={value}>{value}</option>)}</select></label>
      <label>Reported by<select value={form.reported_by} onChange={event=>setForm({...form,reported_by:event.target.value})}>{['Citizen','Authority','Police','Sensor'].map(value=><option key={value}>{value}</option>)}</select></label>
      <label>Reported injuries<input type="number" min="0" max="1000" step="1" value={form.reported_injuries} onChange={event=>setForm({...form,reported_injuries:Number(event.target.value)})}/></label>
      <button className="button button-dark" type="submit" disabled={busy||training}><Sparkles size={15}/>{busy?'Requesting estimate…':'Estimate duration'}</button>
    </form>
    {requiresUrgentReview&&<div className="emergency-review" role="alert"><ShieldAlert size={17}/><span><strong>Urgent human assessment</strong>Critical severity, high severity with injuries, or a collision with 5+ reported injuries requires review under local emergency protocol. This rule is independent of predicted duration.</span></div>}
    {error&&<div className="notice notice-error" role="alert"><AlertTriangle size={16}/><span><strong>Prediction unavailable</strong>{error}</span></div>}
    {result&&<><div className="prediction-result" role="status"><span>{result.model} · historical resolution-duration estimate</span><strong>{formatHours(Number(result.estimated_resolution_hours))}</strong><small>{result.estimated_resolution_hours} hours · {result.disclaimer}</small></div>{result.input_support_warnings?.map((warning:string)=><div className="notice notice-neutral" role="note" key={warning}><CircleHelp size={15}/>{warning}</div>)}<div className="rf-priority-result"><strong>{result.priority_recommendation?.level?.replaceAll('_',' ')}</strong><span>{result.priority_recommendation?.reason}</span><small>Priority rule does not use predicted resolution duration.</small></div><small className="rf-limitation">This predicts time to resolution, not first-response time. Historical metadata estimate only; no guaranteed completion time.</small></>}
  </section>
}

function AlertView({alerts,onSelect}:{alerts:Row[];onSelect:(id:string)=>void}) { return <section className="panel alert-list-panel"><div className="panel-heading"><div><div className="panel-eyebrow">REVIEW SIGNALS · {alerts.length} ITEMS</div><h2>Alerts with supporting evidence</h2></div><span className="subtle-tag">Historical screen</span></div><div className="alert-list">{alerts.map(alert=><article key={alert.id} className="alert-card"><div className={`alert-mark ${alert.severity==='context'?'context-mark':''}`}><AlertTriangle size={16}/></div><div className="alert-card-main"><div><strong>{alert.type}</strong><span className={alert.severity==='context'?'context-label':'review-label'}>{alert.severity==='context'?'CONTEXT REVIEW':'REVIEW'}</span></div><p>{alert.reason}</p><div className="alert-evidence">{Object.entries(alert.evidence??{}).map(([key,value])=><span key={key}><small>{key.replaceAll('_',' ')}</small><strong>{String(value)}</strong></span>)}</div></div><button className="button button-outline" onClick={()=>onSelect(alert.location_id)}>{alert.location_id}<ArrowRight size={14}/></button></article>)}{!alerts.length&&<div className="empty-state">No alerts were generated from the supplied records.</div>}</div><div className="notice notice-neutral"><CircleHelp size={16}/><span>Proximity to schools and hospitals is contextual information only; it is not evidence of danger. An anomaly is a statistical difference, not a confirmed problem.</span></div></section> }

function Settings({quality,status,onRefresh,onTrain}:{quality:Row|null;status:Row|null;onRefresh:()=>void;onTrain:()=>void}) { const datasets=quality?.datasets??{};return <><div className="settings-actions"><section className="panel settings-card"><div className="settings-icon"><Database size={18}/></div><div><span className="panel-eyebrow">LOCAL CSV FILES</span><h2>Dataset integrity</h2><p>Source records stay in the workspace. Refresh reloads and rechecks the aggregates.</p></div><button className="button button-outline" onClick={onRefresh}><RefreshCw size={15}/> Refresh aggregates</button></section><section className="panel settings-card"><div className="settings-icon settings-icon-amber"><Sparkles size={18}/></div><div><span className="panel-eyebrow">MODEL ARTIFACTS</span><h2>Training status</h2><p>{status?.manual_linear_regression?'NumPy model available locally.':'No saved NumPy model is currently loaded.'}</p></div><button className="button button-dark" onClick={onTrain}><RefreshCw size={15}/> Retrain</button></section></div><section className="panel quality-panel"><div className="panel-heading"><div><div className="panel-eyebrow">DATA QUALITY REPORT</div><h2>Records, missing values, and join coverage</h2></div><span className="subtle-tag">Join key: location_id</span></div><div className="quality-coverage"><div><span>Locations</span><strong>{fmt(quality?.location_count)}</strong></div><div><span>Incident join coverage</span><strong>{fmt((quality?.incident_join_coverage??0)*100,1)}%</strong></div><div><span>Complaint join coverage</span><strong>{fmt((quality?.complaint_join_coverage??0)*100,1)}%</strong></div><div><span>Incident date range</span><strong>{quality?.incident_date_range?.join(' → ')??'—'}</strong></div></div><div className="table-scroll"><table className="quality-table"><thead><tr><th>Dataset</th><th>Records</th><th>Unique locations</th><th>Duplicate IDs</th><th>Missing values</th></tr></thead><tbody>{Object.entries(datasets).map(([name,value]:[string,any])=><tr key={name}><td><strong>{name.replaceAll('_',' ')}</strong></td><td>{fmt(value.records)}</td><td>{fmt(value.locations_covered)}</td><td>{fmt(value.duplicate_ids)}</td><td>{fmt(Object.values(value.missing??{}).reduce<number>((sum,item)=>sum+Number(item),0))}</td></tr>)}</tbody></table></div></section><div className="notice notice-neutral"><ShieldAlert size={16}/><span><strong>Prototype limitation:</strong> supplied coordinates are simulated, all records are synthetic and historical, and priority outputs are screening heuristics. Do not use for actual safety decisions.</span></div></> }

function ForecastView({data}:{data:Row|null}) {
  const chartRows=[...(data?.history??[]).map((row:Row)=>({date:row.date,observed:row.count,forecast:null,lower:null,upper:null})),...(data?.forecast??[]).map((row:Row)=>({date:row.date,observed:null,forecast:row.predicted,lower:row.lower,upper:row.upper}))]
  return <><div className="panel forecast-panel"><div className="panel-heading"><div><div className="panel-eyebrow">INCIDENT VOLUME · WEEKLY</div><h2>Short-horizon baseline</h2></div><span className="subtle-tag">Four weeks · historical only</span></div><p className="forecast-description">A rolling four-week average compared with recent history. This is a simple operational reference, not a learned long-range forecast.</p><div className="forecast-stats"><span><small>Rolling four-week MAE</small><strong>{fmt(data?.evaluation?.rolling_four_week_mae,1)}</strong></span><span><small>Previous-week baseline MAE</small><strong>{fmt(data?.evaluation?.previous_week_mae,1)}</strong></span><span><small>Held-out weeks</small><strong>{fmt(data?.evaluation?.test_weeks)}</strong></span></div><div className="chart-area chart-area-tall"><ResponsiveContainer width="100%" height="100%"><LineChart data={chartRows}><CartesianGrid vertical={false} stroke="#e9e8e3" strokeDasharray="3 5"/><XAxis dataKey="date" tickFormatter={shortDate} tickLine={false} axisLine={false} minTickGap={28}/><YAxis tickLine={false} axisLine={false} width={42}/><Tooltip labelFormatter={value=>shortDate(String(value))}/><Line dataKey="observed" name="Observed weekly count" stroke="#287a70" strokeWidth={2} dot={false} connectNulls={false}/><Line dataKey="forecast" name="Baseline estimate" stroke="#c28e43" strokeWidth={2} strokeDasharray="5 4" dot={{r:3}} connectNulls={false}/><Line dataKey="lower" name="Indicative lower bound" stroke="#bdcdbf" strokeDasharray="3 4" dot={false}/><Line dataKey="upper" name="Indicative upper bound" stroke="#bdcdbf" strokeDasharray="3 4" dot={false}/></LineChart></ResponsiveContainer></div><div className="notice notice-neutral"><CircleHelp size={16}/><span>{data?.limitations} {data?.baseline}</span></div></div></>
}

function LocationDetail({detail,modelMetrics,onMap,onQueue}:{detail:Row;modelMetrics:Row|null;onMap:()=>void;onQueue:()=>void}) {
  const location=detail.location, priority=detail.priority
  const severityRows=Object.entries(detail.severity_distribution??{}).map(([name,count])=>({name,count:Number(count)}))
  const complaintRows=Object.entries(detail.complaint_distribution??{}).map(([name,count])=>({name,count:Number(count)}))
  const monthly=detail.incidents.reduce((acc:Record<string,number>,row:Row)=>{const key=String(row.timestamp).slice(0,7);acc[key]=(acc[key]??0)+1;return acc}, {})
  const trendRows=Object.entries(monthly).sort(([a],[b])=>a.localeCompare(b)).map(([month,count])=>({month:month.slice(5),count}))
  const components=Object.entries(priority.components??{}).map(([name,value])=>({name:name.replaceAll('_',' '),value:Number(value)})).sort((a,b)=>b.value-a.value)
  return <><div className="detail-heading panel"><div><span className="panel-eyebrow">{location.zone} · {location.road_type} · {location.road_condition.toUpperCase()} ROAD CONDITION</span><h2>{location.location_id}</h2><p>Simulated coordinate {Number(location.latitude).toFixed(4)}, {Number(location.longitude).toFixed(4)} · population density {fmt(location.population_density_per_km2)}/km²</p></div><div className="detail-actions"><button className="button button-outline" onClick={onMap}><MapPin size={15}/> Show on map</button><button className="button button-dark" onClick={onQueue}><ClipboardList size={15}/> Queue</button></div></div><div className="metric-grid detail-metrics"><Metric label="Screening score" value={`${fmt(priority.priority_score,1)}/100`} detail={`${priority.evidence_strength} evidence strength`} icon={Gauge} tone="tone-amber"/><Metric label="Incident records" value={fmt(priority.incident_count)} detail={`${fmt(priority.severe_incidents)} high or critical`} icon={TrafficCone} tone="tone-teal"/><Metric label="Reported injuries" value={fmt(priority.injuries)} detail={`${fmt(priority.unresolved_incidents)} unresolved incidents`} icon={ShieldAlert} tone="tone-rose"/><Metric label="Open complaints" value={fmt(priority.open_complaints)} detail={`average open age ${fmt(priority.complaint_age_days,1)} days`} icon={Clock3} tone="tone-ink"/></div><div className="overview-grid detail-grid"><section className="panel detail-panel"><div className="panel-heading"><div><div className="panel-eyebrow">OBSERVED INCIDENTS</div><h2>Incident history by month</h2></div><span className="subtle-tag">{detail.incidents.length} records</span></div><div className="chart-area chart-area-tall"><ResponsiveContainer width="100%" height="100%"><BarChart data={trendRows}><CartesianGrid vertical={false} stroke="#e9e8e3" strokeDasharray="3 5"/><XAxis dataKey="month" tickLine={false} axisLine={false}/><YAxis tickLine={false} axisLine={false} width={35}/><Tooltip/><Bar dataKey="count" name="Incidents" fill="#287a70" radius={[3,3,0,0]}/></BarChart></ResponsiveContainer></div><div className="detail-breakdown"><h3>Severity distribution</h3>{severityRows.map(row=><span key={row.name}><b>{row.name}</b><strong>{fmt(row.count)}</strong></span>)}</div></section><section className="panel detail-panel"><div className="panel-heading"><div><div className="panel-eyebrow">PUBLIC COMPLAINTS</div><h2>Category mix</h2></div><span className="subtle-tag">{detail.complaints.length} records</span></div><div className="category-chart category-chart-large"><ResponsiveContainer width="100%" height="100%"><BarChart data={complaintRows} layout="vertical" margin={{left:4,right:16}}><XAxis type="number" hide/><YAxis type="category" dataKey="name" width={115} tickLine={false} axisLine={false} tick={{fontSize:10,fill:'#6f7773'}}/><Tooltip/><Bar dataKey="count" name="Complaints" fill="#c28e43" radius={[0,3,3,0]} barSize={17}/></BarChart></ResponsiveContainer></div><div className="detail-resolution"><span>Resolved incident mean <strong>{fmt(detail.resolution_hours.mean,1)}h</strong></span><span>Median <strong>{fmt(detail.resolution_hours.median,1)}h</strong></span><span>Same-zone mean <strong>{fmt(detail.comparison.zone_average_per_location,1)} per location</strong></span></div></section></div><div className="overview-grid detail-grid"><section className="panel detail-panel"><div className="panel-heading"><div><div className="panel-eyebrow">SCORE EVIDENCE</div><h2>Component breakdown</h2></div><span className="subtle-tag">Heuristic components</span></div><div className="component-list">{components.map(item=><div key={item.name}><span>{item.name}</span><div className="component-track"><i style={{width:`${Math.min(item.value,100)}%`}}/></div><strong>{fmt(item.value,1)}</strong></div>)}</div><p className="score-disclaimer">Percentile-scaled components are weighted in the published formula. The score is not a probability of harm or validated risk metric.</p></section><section className="panel detail-panel"><div className="panel-heading"><div><div className="panel-eyebrow">MODEL OUTPUTS</div><h2>Resolution-time estimates</h2></div><Sparkles size={16} className="help-icon"/></div><div className="prediction-pair"><div><span>Incident resolution</span><strong>{fmt(detail.prediction.incident_resolution_hours,1)} <small>hours</small></strong><small>NumPy linear regression · held-out MAE {fmt(modelMetrics?.manual_linear_regression?.manual_linear_regression?.metrics?.mae,2)} h</small></div><div><span>Complaint resolution</span><strong>{fmt(detail.prediction.complaint_resolution_days,1)} <small>days</small></strong><small>Historical metadata estimate; not a guarantee</small></div></div><div className="recommendation-box"><span className="panel-eyebrow">SUGGESTED NEXT INVESTIGATION</span><p>{priority.recommendation}</p><small>Context: {location.near_school?'near-school flag present; human review only. ':''}{location.near_hospital?'near-hospital flag present; human review only. ':''}Pedestrian activity is {location.pedestrian_activity.toLowerCase()}.</small></div></section></div><div className="notice notice-neutral"><ShieldAlert size={16}/><span><strong>Limitations:</strong> {detail.limitations.join(' ')} Priority evidence: {priority.evidence_strength.toLowerCase()}, determined by independent signal counts and observed incident volume, not model confidence.</span></div></>
}

export default App
